bounded_host_request.command:
set -eu
topic_count="$(docker exec deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Atc "SELECT count(*) FROM posting_topics WHERE purpose='\''video_sale'\'' AND chat_id=-1002373696859 AND enabled=true AND verified_by IS NOT NULL AND verified_at IS NOT NULL;"')"
echo "TOPIC_COUNT=$topic_count"
test "$topic_count" = 1 || exit 61
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const e=process.env;
const u=e.VIDEOBOT_DATABASE_URL_FILE?readFileSync(e.VIDEOBOT_DATABASE_URL_FILE,'utf8').trim():'postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim())+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const c=new pg.Client({connectionString:u,connectionTimeoutMillis:5000});
try{
 await c.connect();
 const r=await c.query("select status, rights_verified,adult_consent_verified,fee_terms_accepted_at is not null as terms,thumbnail_file_id is not null as thumbnail,sample_file_id is not null as sample,paid_video_file_id is not null as video from videobot_listings where status='draft' limit 2");
 console.log('DRAFT_ROWS='+r.rowCount);
 for(const row of r.rows)console.log('DRAFT_ELIGIBILITY='+JSON.stringify(row));
}finally{await c.end().catch(()=>{})}
NODE
